import{test}from'node:test';import assert from'node:assert/strict';import{mapSize,validateMapImage,mapRequest}from'./wms-client.js';
test('map dimensions preserve WGS84 image aspect and advertised edge limits',()=>{assert.deepEqual(mapSize([0,0,4,2],1024),[1024,512]);assert.deepEqual(mapSize([0,0,4,2],2048,512,2048),[512,256]);assert.equal(mapSize([4,0,0,2],1024),null);});
test('saved map grid accepts numeric equivalents but rejects changed axis, dimensions and duplicate parameters',()=>{
  const id='735f227b-5f95-473f-967b-077f3419bc68',endpoint='https://maps.example.com/wms';const url=new URL(endpoint);for(const[k,v]of Object.entries({SERVICE:'WMS',VERSION:'1.3.0',REQUEST:'GetMap',LAYERS:'land',STYLES:'',CRS:'EPSG:4326',BBOX:'30,-125,43,-110',WIDTH:'512',HEIGHT:'444',FORMAT:'image/png',TRANSPARENT:'TRUE',TIME:'2025-06-27'}))url.searchParams.set(k,v);
  const asset={id,name:'Land image',bounds:[-125,30,-110,43],crs:'EPSG:4326',width:512,height:444,bytes:100,sha256:'a'.repeat(64),source:{serviceUrl:endpoint,mapEndpoint:endpoint,version:'1.3.0',requestCrs:'EPSG:4326',selection:'bbox-rendered-map',capabilitiesSha256:'b'.repeat(64),layerName:'land',layerTitle:'Land',style:'',time:'2025-06-27',requestedAt:'2026-10-02T00:00:00Z',requestUrl:url.href}};
  validateMapImage(asset);const tiny={...asset,bounds:[-0.0000001,30,0.0000001,43],source:{...asset.source}};const tinyUrl=new URL(url);tinyUrl.searchParams.set('BBOX','30,-0.0000001,43,0.0000001');tiny.source.requestUrl=tinyUrl.href;validateMapImage(tiny);
  assert.throws(()=>validateMapImage({...asset,width:513}),/grid/);const changed=new URL(url);changed.searchParams.set('BBOX','-125,30,-110,43');assert.throws(()=>validateMapImage({...asset,source:{...asset.source,requestUrl:changed.href}}),/grid/);url.searchParams.append('TIME','2025-06-27');assert.throws(()=>validateMapImage({...asset,source:{...asset.source,requestUrl:url.href}}),/grid/);
});
test('native string exceptions remain readable errors',async()=>{globalThis.window={__TAURI__:{core:{invoke:async()=>{throw 'WMS exception';}}}};try{await assert.rejects(mapRequest('services'),/WMS exception/);}finally{delete globalThis.window;}});
